   written). Then halt. */
#include "board.h"

static void access(u32 k, u32 word)
{
    u32 polls = 0u;
    USB_PORT = word;
    while ((USB_PORT & 0x8000u) == 0u && polls < 1000u) {
        polls++;
    }
    OUT(2u * k) = polls;
    OUT(2u * k + 1u) = USB_PORT;
}

int main(void)
{
    access(0u, 0x0b5au);
    access(1u, 0x4b00u);
    access(2u, 0x06ffu);
    access(3u, 0x4600u);
    access(4u, 0x4100u);
    return 0;
}

